describe('Table Row Context Menu - Right Click', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should display context menu when right-clicking a table row', () => {
    // Locate the first table row
    cy.get('[data-testid="table-row-1"]').as('firstRow');

    // Right-click on the first table row
    cy.get('@firstRow').rightclick();

    // Verify context menu appears
    cy.get('[data-testid="context-menu"]').should('be.visible');

    // Verify context menu contains expected options
    cy.get('[data-testid="context-menu"]').should('contain', 'Edit Row');
    cy.get('[data-testid="context-menu"]').should('contain', 'Delete Row');
    cy.get('[data-testid="context-menu"]').should('contain', 'View Details');

    // Verify context menu is positioned correctly relative to the row
    cy.get('[data-testid="context-menu"]').should('have.css', 'top');
    cy.get('[data-testid="context-menu"]').should('have.css', 'left');

    // Verify row is still visible and interactive
    cy.get('@firstRow').should('be.visible');
    cy.get('@firstRow').should('contain', 'Row 1');
  });

  it('should close context menu when clicking outside of it', () => {
    // Locate the first table row and right-click
    cy.get('[data-testid="table-row-1"]').rightclick();

    // Verify context menu is visible
    cy.get('[data-testid="context-menu"]').should('be.visible');

    // Click on a different element on the page (outside the context menu)
    cy.get('[data-testid="table-header"]').click();

    // Verify context menu is closed
    cy.get('[data-testid="context-menu"]').should('not.exist');

    // Verify the table row is still visible
    cy.get('[data-testid="table-row-1"]').should('be.visible');
  });
});
